  it('should strip www. for hostname with 63-character TLD', () => {
    const tld = 'a'.repeat(63);
    const url = `http://www.example.${tld}`;
    const expected = `http://example.${tld}`;
    const actual = normalizeUrl(url);
    assert.strictEqual(actual, expected);
  });
